SELECT CASE WHEN CAST(registered_at AS DATE) BETWEEN DATE '2026-07-01' AND DATE '2026-07-14' THEN '前期' ELSE '近期' END AS period, COUNT(*) AS new_users FROM users WHERE (CAST(registered_at AS DATE) BETWEEN DATE '2026-07-01' AND DATE '2026-07-14' OR CAST(registered_at AS DATE) BETWEEN DATE '2026-07-22' AND DATE '2026-08-04') GROUP BY period;
